require('dotenv').config({quiet:true});
const {chromium}=require('playwright');
const fs=require('fs');
const assert=require('assert/strict');
(async()=>{
 const mode=process.argv[2]; const dir='../answers/BUG-01/evidence'; fs.mkdirSync(dir,{recursive:true});
 const browser=await chromium.launch({headless:true}); const page=await browser.newPage({viewport:{width:1440,height:1000}});
 await page.goto('http://localhost:3020/login'); await page.locator('#email').fill(process.env.ADMIN_EMAIL); await page.locator('#password').fill(process.env.ADMIN_PASSWORD); await page.getByRole('button',{name:'Sign in',exact:true}).click(); await page.waitForURL('**/dashboard');
 const results=[];
 async function check(path,width,file){
  await page.setViewportSize({width,height:1000}); await page.goto('http://localhost:3020'+path); await page.waitForTimeout(1800);
  const rect=await page.evaluate(()=>{const nav=[...document.querySelectorAll('nav')].find(n=>getComputedStyle(n).display!=='none');const m=document.querySelector('main').getBoundingClientRect();const h=document.querySelector('header').getBoundingClientRect();const n=nav.getBoundingClientRect();return {main:m.x,header:h.x,navRight:n.right,navWidth:n.width,navTop:n.top,body:document.documentElement.scrollWidth};});
  await page.screenshot({path:dir+'/'+file,fullPage:true});
  if(mode==='before'){assert(rect.main<rect.navRight);}
  else if(width>=768){assert(rect.main>=rect.navRight);assert(rect.header>=rect.navRight);}
  else {assert.equal(rect.main,0);assert.equal(rect.header,0);assert(rect.navTop>800);await page.getByRole('link',{name:'Money',exact:true}).click();await page.waitForURL('**/accounting'); await page.getByRole('link',{name:'Home',exact:true}).click();await page.waitForURL('**/dashboard');}
  results.push({path,width,...rect,pass:true});
 }
 if(mode==='before')await check('/dashboard',1440,'dashboard_before_fixing.png');
 else if(mode==='dev'){await check('/dashboard',1440,'tc-01-desktop-dashboard.png');await check('/dashboard',390,'tc-03-mobile-dashboard.png');await check('/accounting',390,'tc-03-mobile-accounting.png');}
 else {await check('/accounting',1024,'tc-02-production-layout.png');await check('/boards',1024,'tc-02-production-boards.png');await check('/dashboard',1440,'production-dashboard.png');}
 fs.writeFileSync(dir+'/'+mode+'-layout.json',JSON.stringify(results,null,2)); await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

